using System;
using System.Collections.Generic;
using System.Linq;

public enum EntryType { Debit, Credit }

public record LedgerEntry(string AccountNumber, EntryType Type, decimal Amount);

public class JournalTransaction
{
    public Guid Id { get; } = Guid.NewGuid();
    public DateTime Timestamp { get; } = DateTime.UtcNow;
    public string Description { get; }
    private readonly List<LedgerEntry> _entries = new();

    public IReadOnlyCollection<LedgerEntry> Entries => _entries.AsReadOnly();

    public JournalTransaction(string description) => Description = description;

    public void AddEntry(string accountNumber, EntryType type, decimal amount)
    {
        if (amount <= 0) throw new ArgumentException("Nominal harus positif!");
        _entries.Add(new LedgerEntry(accountNumber, type, amount));
    }

    public bool ValidateBalanced()
    {
        if (_entries.Count < 2) return false;

        decimal totalDebit = _entries.Where(e => e.Type == EntryType.Debit).Sum(e => e.Amount);
        decimal totalCredit = _entries.Where(e => e.Type == EntryType.Credit).Sum(e => e.Amount);

        return totalDebit == totalCredit;
    }
}

public class Program
{
    public static void Main()
    {
        var tx = new JournalTransaction("Transfer Dana Alice ke Bob");
        tx.AddEntry("ACC_ALICE", EntryType.Debit, 250_000m);
        tx.AddEntry("ACC_BOB", EntryType.Credit, 250_000m);

        bool isBalanced = tx.ValidateBalanced();
        Console.WriteLine($"Transaksi 1 Seimbang (Debit == Kredit)? : {isBalanced} (Ekspektasi: True)");

        var badTx = new JournalTransaction("Transaksi Gagal Seimbang");
        badTx.AddEntry("ACC_ALICE", EntryType.Debit, 500_000m);
        badTx.AddEntry("ACC_BOB", EntryType.Credit, 450_000m);

        Console.WriteLine($"Transaksi 2 Seimbang?                   : {badTx.ValidateBalanced()} (Ekspektasi: False)");
    }
}
